<?php
namespace App\Http\Controllers\Api\Admin;
use App\Http\Controllers\Controller;use App\Models\Attendance;use App\Services\AttendanceReportService;use Illuminate\Http\Request;
use Dompdf\Dompdf;use PhpOffice\PhpSpreadsheet\Spreadsheet;use PhpOffice\PhpSpreadsheet\Writer\Xlsx;
class AttendanceReportController extends Controller { public function __construct(private AttendanceReportService $reports){} private function filters(Request $r):array{return $r->validate(['from'=>['nullable','date'],'to'=>['nullable','date','after_or_equal:from'],'employee_id'=>['nullable','integer','exists:employees,id'],'department_id'=>['nullable','integer','exists:departments,id'],'office_id'=>['nullable','integer','exists:offices,id'],'status'=>['nullable','in:present,late,half_day,partial,absent,work_from_home'],'mode'=>['nullable','in:office,wfh'],'search'=>['nullable','string','max:100'],'sort'=>['nullable','in:attendance_date,working_minutes,late_minutes'],'direction'=>['nullable','in:asc,desc'],'per_page'=>['nullable','integer','min:1','max:100']]);} public function index(Request $r){$f=$this->filters($r);return response()->json($this->reports->query($f)->paginate($f['per_page']??25));} public function show(Attendance $attendance){return response()->json($attendance->load(['employee.department','office','locationLogs'=>fn($q)=>$q->latest('recorded_at')->limit(1)]));} public function export(Request $r,string $format){abort_unless(in_array($format,['csv','xlsx','pdf'],true),404);$f=$this->filters($r);$rows=$this->reports->query($f)->limit(10000)->get()->map(fn($a)=>$this->reports->row($a))->values();if($format==='csv')return response()->streamDownload(function()use($rows){$o=fopen('php://output','w');if($rows->isNotEmpty()){fputcsv($o,array_keys($rows[0]));foreach($rows as $x)fputcsv($o,$x);}fclose($o);},'attendance-report.csv',['Content-Type'=>'text/csv']);if($format==='xlsx'){return response()->streamDownload(function()use($rows){$sheet=(new Spreadsheet)->getActiveSheet();$headers=array_keys($rows->first()??['date'=>'Date']);$sheet->fromArray($headers,null,'A1');foreach($rows as $i=>$row)$sheet->fromArray(array_values($row),null,'A'.($i+2));foreach(range('A',chr(64+count($headers))) as $col)$sheet->getColumnDimension($col)->setAutoSize(true);(new Xlsx($sheet->getParent()))->save('php://output');},'attendance-report.xlsx',['Content-Type'=>'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']);}$headers=array_keys($rows->first()??['date'=>'Date']);$html='<h1>Attendance report</h1><table><tr>'.implode('',array_map(fn($h)=>'<th>'.htmlspecialchars($h).'</th>',$headers)).'</tr>'.implode('', $rows->map(fn($x)=>'<tr>'.implode('',array_map(fn($v)=>'<td>'.htmlspecialchars((string)$v).'</td>',$x)).'</tr>')->all()).'</table>';$pdf=new Dompdf;$pdf->loadHtml('<style>body{font:9px sans-serif}table{border-collapse:collapse;width:100%}td,th{border:1px solid #555;padding:3px}</style>'.$html);$pdf->setPaper('A4','landscape');$pdf->render();return response($pdf->output(),200,['Content-Type'=>'application/pdf','Content-Disposition'=>'attachment; filename="attendance-report.pdf"']);}}
